// machines/plaits: PHASE-DIST's oscillator sample loop (engines/phase_dist.c, pd_osc_render), hand-written SISD kernel.
// Generated by lib/gen_phase_dist_kernel.py; do not edit by hand.
//
// pd_osc_kernel(PdOsc *s, const float *k, float *out, int size, int flags):
//   s = the oscillator (master_phase_, slave_phase_, next_sample_, previous_pw_, high_, then the five interpolators'
//   values master_frequency_, slave_frequency_, pw_, waveshape_, phase_modulation_); k[0..4] = the interpolators'
//   increments; flags bit 0 = enable_sync, bit 1 = output_phase off (PHASE-DIST passes enable_sync with output_phase
//   on; VA's shape_render, the same VariableShapeOscillator with output_phase off, passes 3: *out = 2 this_sample - 1
//   and phase_modulation is not stepped). Writes `size` samples to out and the state back (the values are the
//   interpolators' commits),
//   bit-identical to selcc's code of the C loop (-DPL_PD_C): the same operations with the same operands in the same
//   order (tests/plaits/test_phase_dist_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, M6, L0, L1, L4 pushed through R0, M6 = 1 and L0 = L1 = L4 = 0 set here). No SIMD, no DO loop.
// Registers in the loop: R15 master phase, R14 slave phase, R13 next_sample, R12 this_sample, R11 high_, R10 slave
// frequency, R9 pw; I1 = s, I4 = k, I0 = out; the other per-sample values live in frame slots above I7.
//
// ABI: as the other kernels (lib/wavetable_sm.s): relies on M5 = 0 and M7 = -1, sets M6 = 1 itself; DAG registers
// are pushed through R0 and restored by loads through I7. Assembled under .COMPRESS (the assembler leaves the
// instructions of a DO loop in their 48-bit forms, as the PRM requires for a loop's last 11): smaller hot code.

//
// pd_down_kernel(const float *temp, float *out, float *aux, int size, const float *lut_sine): phase_dist_render's
//   naive 2x downsampling: out[i] = 0.5 sine(temp[2i] + 0.25) + 0.5 sine(temp[2i + 1] + 0.25), aux[i] the same from
//   temp[2 size + 2i ..], sine = phase_dist_sine (a negative phase wrapped by its integer part plus one, computed for
//   every sample and selected, then InterpolateWrap over 512 points with itof_nonneg written out). Two sines per
//   iteration interleaved (each table row's DAG write four instructions before its reads). Changes R0-R8, R12, I4 and
//   the flags; restores the rest (I0, I1, I5, M6, L0, L1, L4, L5 pushed through R0).

.SECTION/PM seg_pmco;
.GLOBAL pd_osc_kernel.;
.GLOBAL pd_down_kernel.;
.COMPRESS;

pd_osc_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I7=MODIFY (I7,-19)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(1, I6);                                     // size
    DM(17, I7) = R0;
    R1 = DM(2, I6);                                     // flags: bit 0 enable_sync, bit 1 no output_phase
    R2 = 1;
    R2 = R1 AND R2;
    DM(18, I7) = R2;
    R2 = 2;
    R2 = R1 AND R2;
    DM(19, I7) = R2;
    R15 = DM(0, I1);                                    // master_phase_
    R14 = DM(1, I1);                                    // slave_phase_
    R13 = DM(2, I1);                                    // next_sample_
    R2 = DM(3, I1);                                     // previous_pw_
    DM(16, I7) = R2;
    R11 = DM(4, I1);                                    // high_
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _pdk_done;
_pdk_loop:
    R12 = PASS R13;                                     // this_sample = next_sample
    R13 = 0;                                            // next_sample = 0.0f
    R0 = DM(5, I1);
    R1 = DM(0, I4);
    F0 = F0 + F1;                                       // master_f = master_fm.Next()
    DM(5, I1) = R0;
    DM(12, I7) = R0;
    R0 = DM(6, I1);
    R1 = DM(1, I4);
    F10 = F0 + F1;                                      // slave_frequency
    DM(6, I1) = R10;
    R0 = DM(7, I1);
    R1 = DM(2, I4);
    F9 = F0 + F1;                                       // pw
    DM(7, I1) = R9;
    R0 = DM(8, I1);
    R1 = DM(3, I4);
    F1 = F0 + F1;                                       // ws
    DM(8, I1) = R1;
    R2 = 0x3F000000;
    F2 = F1 - F2;                                       // ws - 0.5f
    R0 = 0;
    COMP(F2, F0);                                       // maxf(.., 0.0f)
    IF LE R2 = R0 OR R0;
    R5 = 0x40000000;
    F2 = F2 * F5;                                       // square_amount
    DM(10, I7) = R2;
    F3 = F1 * F5;                                       // ws * 2.0f
    R6 = 0x3F800000;
    F3 = F6 - F3;
    COMP(F3, F0);                                       // maxf(.., 0.0f)
    IF LE R3 = R0 OR R0;
    DM(11, I7) = R3;                                    // triangle_amount
    R0 = 0x3F800000;
    R3 = 0x40000000;
    R7 = 0x40000000;
    F4 = F0 - F9;                                       // 1.0f - pw
    F1 = RECIPS F9;
    F5 = RECIPS F4;
    F2 = F9 * F1;                                       // slope_up, slope_down: selcc divisions
    F6 = F4 * F5;
    F2 = F3 - F2;
    F6 = F7 - F6;
    F1 = F1 * F2;
    F5 = F5 * F6;
    F2 = F9 * F1;
    F6 = F4 * F5;
    F2 = F3 - F2;
    F6 = F7 - F6;
    F1 = F1 * F2;
    F5 = F5 * F6;
    F3 = F0 * F1;
    F7 = F0 * F5;
    F2 = F9 * F3;
    F6 = F4 * F7;
    F2 = F0 - F2;
    F6 = F0 - F6;
    F2 = F2 * F1;
    F6 = F6 * F5;
    F3 = F3 + F2;
    F7 = F7 + F6;
    DM(8, I7) = R3;                                     // slope_up
    DM(9, I7) = R7;                                     // slope_down
    R0 = 0;
    DM(14, I7) = R0;                                    // reset = 0
    DM(15, I7) = R0;                                    // transition_during_reset = 0
    R1 = DM(12, I7);
    R0 = DM(18, I7);
    R2 = 0;
    COMP(R0, R2);
    IF EQ JUMP _pdk_free;
    F15 = F15 + F1;                                     // master_phase_ += master_f
    R2 = 0x3F800000;
    COMP(F15, F2);                                      // master_phase_ >= 1.0f
    IF LT JUMP _pdk_sp;
    F15 = F15 - F2;
    R4 = 0x40000000;
    F3 = RECIPS F1;
    F5 = F1 * F3;                                       // reset_time = master_phase_ / master_f
    F5 = F4 - F5;
    F3 = F3 * F5;
    F5 = F1 * F3;
    F5 = F4 - F5;
    F3 = F3 * F5;
    F4 = F15 * F3;
    F5 = F1 * F4;
    F5 = F15 - F5;
    F5 = F5 * F3;
    F0 = F4 + F5;
    DM(13, I7) = R0;
    R2 = 0x3F800000;
    F3 = F2 - F0;                                       // slave_phase_at_reset
    F3 = F3 * F10;
    F3 = F14 + F3;
    R5 = 1;
    DM(14, I7) = R5;                                    // reset = 1
    COMP(F3, F2);                                       // slave_phase_at_reset >= 1.0f
    IF LT JUMP _pdk_s1;
    F3 = F3 - F2;
    DM(15, I7) = R5;
_pdk_s1:
    R6 = 0;
    COMP(R11, R6);                                      // !high_
    IF NE JUMP _pdk_s2;
    COMP(F3, F9);                                       // slave_phase_at_reset >= pw
    IF LT JUMP _pdk_s2;
    DM(15, I7) = R5;
_pdk_s2:
    R1 = DM(8, I7);                                     // pd_naive(F3)
    R2 = DM(9, I7);
    R8 = 0x3F800000;
    F4 = F3 * F1;                                       // phase * slope_up
    F5 = F3 - F9;
    F5 = F5 * F2;
    F5 = F8 - F5;                                       // 1 - (phase - pw) * slope_down
    R0 = 0;
    COMP(F3, F9);                                       // square = phase < pw ? 0 : 1
    IF GE R0 = R8 OR R8;
    COMP(F3, F9);                                       // triangle
    IF GE R4 = R5 OR R5;
    R6 = DM(10, I7);
    F0 = F0 - F3;                                       // saw += (square - saw) * square_amount
    F0 = F0 * F6;
    F0 = F3 + F0;
    R7 = DM(11, I7);
    F4 = F4 - F0;                                       // saw += (triangle - saw) * triangle_amount
    F4 = F4 * F7;
    F0 = F0 + F4;
    R3 = PASS R0;                                       // value
    R2 = DM(13, I7);
    R0 = 0x3F000000;
    F0 = F0 * F2;                                       // ThisBlepSample(reset_time)
    F0 = F0 * F2;
    F0 = F3 * F0;
    F12 = F12 - F0;                                     // this_sample -= value * ..
    R1 = 0x3F800000;
    F2 = F1 - F2;                                       // NextBlepSample(reset_time)
    R0 = 0xBF000000;
    F0 = F0 * F2;
    F0 = F0 * F2;
    F0 = F3 * F0;
    F13 = F13 - F0;                                     // next_sample -= value * ..
    JUMP _pdk_sp;
_pdk_free:
    R0 = DM(19, I7);
    R2 = 0;
    COMP(R0, R2);                                       // neither sync nor output_phase: the master phase stays
    IF NE JUMP _pdk_sp;
    F15 = F15 + F1;                                     // master_phase_ += master_f
    R2 = 0x3F800000;
    COMP(F15, F2);                                      // master_phase_ >= 1.0f
    IF LT JUMP _pdk_sp;
    F15 = F15 - F2;
_pdk_sp:
    F14 = F14 + F10;                                    // slave_phase_ += slave_frequency
    R0 = DM(15, I7);
    R2 = 0;
    COMP(R0, R2);
    IF NE JUMP _pdk_wtop;
    R1 = DM(14, I7);
    COMP(R1, R2);
    IF NE JUMP _pdk_wend;
_pdk_wtop:
    R2 = 0;
    COMP(R11, R2);                                      // if (!high_)
    IF NE JUMP _pdk_hi;
    COMP(F14, F9);                                      // slave_phase_ < pw: break
    IF LT JUMP _pdk_wend;
    R0 = DM(16, I7);
    F0 = F0 - F9;                                       // previous_pw_ - pw + slave_frequency
    F0 = F0 + F10;
    F1 = F14 - F9;                                      // slave_phase_ - pw
    R4 = 0x40000000;
    F3 = RECIPS F0;
    F5 = F0 * F3;                                       // t
    F5 = F4 - F5;
    F3 = F3 * F5;
    F5 = F0 * F3;
    F5 = F4 - F5;
    F3 = F3 * F5;
    F4 = F1 * F3;
    F5 = F0 * F4;
    F5 = F1 - F5;
    F5 = F5 * F3;
    F2 = F4 + F5;
    R6 = DM(8, I7);
    R7 = DM(9, I7);
    F6 = F6 + F7;                                       // triangle_step
    F6 = F6 * F10;
    R7 = DM(11, I7);
    F6 = F6 * F7;
    R8 = DM(10, I7);
    R0 = 0x3F000000;
    F0 = F0 * F2;                                       // ThisBlepSample(t)
    F0 = F0 * F2;
    F0 = F8 * F0;
    F12 = F12 + F0;                                     // this_sample += square_amount * ..
    R1 = 0x3F800000;
    F3 = F1 - F2;                                       // 1 - t
    R0 = 0xBF000000;
    F0 = F0 * F3;                                       // NextBlepSample(t)
    F0 = F0 * F3;
    F0 = F8 * F0;
    F13 = F13 + F0;                                     // next_sample += square_amount * ..
    R0 = 0x3F000000;
    F4 = F0 * F3;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // ThisIntegratedBlepSample(t)
    F12 = F12 - F1;                                     // this_sample -= triangle_step * ..
    R0 = 0x3F000000;
    F4 = F0 * F2;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // NextIntegratedBlepSample(t)
    F13 = F13 - F1;                                     // next_sample -= triangle_step * ..
    R11 = 1;                                            // high_ = 1
_pdk_hi:
    R0 = 0x3F800000;
    COMP(F14, F0);                                      // slave_phase_ < 1.0f: break
    IF LT JUMP _pdk_wend;
    F14 = F14 - F0;
    R4 = 0x40000000;
    F3 = RECIPS F10;
    F5 = F10 * F3;                                      // t = slave_phase_ / slave_frequency
    F5 = F4 - F5;
    F3 = F3 * F5;
    F5 = F10 * F3;
    F5 = F4 - F5;
    F3 = F3 * F5;
    F4 = F14 * F3;
    F5 = F10 * F4;
    F5 = F14 - F5;
    F5 = F5 * F3;
    F2 = F4 + F5;
    R6 = DM(8, I7);
    R7 = DM(9, I7);
    F6 = F6 + F7;                                       // triangle_step
    F6 = F6 * F10;
    R7 = DM(11, I7);
    F6 = F6 * F7;
    R1 = 0x3F800000;
    F8 = F1 - F7;                                       // 1.0f - triangle_amount
    R0 = 0x3F000000;
    F0 = F0 * F2;                                       // ThisBlepSample(t)
    F0 = F0 * F2;
    F0 = F8 * F0;
    F12 = F12 - F0;                                     // this_sample -= (1 - triangle_amount) * ..
    F3 = F1 - F2;                                       // 1 - t
    R0 = 0xBF000000;
    F0 = F0 * F3;                                       // NextBlepSample(t)
    F0 = F0 * F3;
    F0 = F8 * F0;
    F13 = F13 - F0;                                     // next_sample -= (1 - triangle_amount) * ..
    R0 = 0x3F000000;
    F4 = F0 * F3;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // ThisIntegratedBlepSample(t)
    F12 = F12 + F1;                                     // this_sample += triangle_step * ..
    R0 = 0x3F000000;
    F4 = F0 * F2;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // NextIntegratedBlepSample(t)
    F13 = F13 + F1;                                     // next_sample += triangle_step * ..
    R11 = 0;                                            // high_ = 0
    JUMP _pdk_wtop;
_pdk_wend:
    R0 = DM(14, I7);
    R1 = 0;
    COMP(R0, R1);                                       // enable_sync && reset (reset is set only with sync)
    IF EQ JUMP _pdk_nr;
    R0 = DM(13, I7);
    F14 = F0 * F10;                                     // slave_phase_ = reset_time * slave_frequency
    R11 = 0;
_pdk_nr:
    R1 = DM(8, I7);                                     // pd_naive(F14)
    R2 = DM(9, I7);
    R8 = 0x3F800000;
    F4 = F14 * F1;                                      // phase * slope_up
    F5 = F14 - F9;
    F5 = F5 * F2;
    F5 = F8 - F5;                                       // 1 - (phase - pw) * slope_down
    R0 = 0;
    COMP(F14, F9);                                      // square = phase < pw ? 0 : 1
    IF GE R0 = R8 OR R8;
    COMP(F14, F9);                                      // triangle
    IF GE R4 = R5 OR R5;
    R6 = DM(10, I7);
    F0 = F0 - F14;                                      // saw += (square - saw) * square_amount
    F0 = F0 * F6;
    F0 = F14 + F0;
    R7 = DM(11, I7);
    F4 = F4 - F0;                                       // saw += (triangle - saw) * triangle_amount
    F4 = F4 * F7;
    F0 = F0 + F4;
    F13 = F13 + F0;                                     // next_sample += pd_naive(..)
    DM(16, I7) = R9;                                    // previous_pw_ = pw
    R0 = DM(19, I7);
    R1 = 0;
    COMP(R0, R1);                                       // output_phase off: *out++ = 2 this_sample - 1
    IF EQ JUMP _pdk_ph;
    R0 = 0x40000000;
    F0 = F0 * F12;
    R1 = 0x3F800000;
    F0 = F0 - F1;
    JUMP _pdk_st;
_pdk_ph:
    R3 = PASS R15;                                      // phasor
    R0 = DM(18, I7);
    R1 = 0;
    COMP(R0, R1);
    IF EQ JUMP _pdk_out;
    R1 = 0x3F800000;
    F0 = F1 - F15;                                      // w = 4 (1 - master_phase_) master_phase_
    R2 = 0x40800000;
    F0 = F2 * F0;
    F0 = F0 * F15;
    R2 = 0x40000000;
    F1 = F2 - F0;                                       // this_sample *= w * (2 - w)
    F1 = F0 * F1;
    F12 = F12 * F1;
    F4 = F15 * F15;                                     // p2
    F5 = F4 * F4;
    F5 = F5 - F15;                                      // p2 * p2 - phasor
    R6 = 0x3F000000;
    F6 = F9 - F6;                                       // absf(pw - 0.5f)
    F7 = -F6;
    R8 = 0;
    COMP(F6, F8);
    IF GE R7 = R6 OR R6;
    F5 = F5 * F7;
    F5 = F5 * F2;                                       // * 2.0f
    F3 = F15 + F5;                                      // phasor += ..
_pdk_out:
    R0 = DM(9, I1);
    R1 = DM(4, I4);
    F0 = F0 + F1;                                       // phase_modulation.Next()
    DM(9, I1) = R0;
    F0 = F0 * F12;
    F0 = F3 + F0;                                       // phasor + .. * this_sample
_pdk_st:
    DM(I0, M6) = R0;
    R0 = DM(17, I7);
    R1 = 1;
    R0 = R0 - R1;
    DM(17, I7) = R0;
    IF NE JUMP _pdk_loop;
_pdk_done:
    DM(0, I1) = R15;
    DM(1, I1) = R14;
    DM(2, I1) = R13;
    R0 = DM(16, I7);
    DM(3, I1) = R0;
    DM(4, I1) = R11;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,19)(NW);
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

pd_down_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I5;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    R0 = L5;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    L5 = 0;
    I7=MODIFY (I7,-7)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    DM(7, I7) = R12;                                    // aux
    I1 = R4;                                            // temp
    I0 = R8;                                            // out
    R10 = DM(2, I6);                                    // lut_sine
    R15 = 0x3E800000;                                   // 0.25f
    R14 = 0x4B000000;                                   // itof_nonneg's bias (as a float: 8388608.0f)
    R13 = 0x44000000;                                   // 512.0f
    R12 = 0x3F000000;
    R11 = 1;
    R9 = 0;
    R8 = DM(1, I6);                                     // size
    COMP(R8, R9);
    IF LE JUMP _pdd_done;
    LCNTR = R8, DO _pdd_e0 UNTIL LCE;
    R0 = DM(I1, M6);                                    // out[i]: two samples A (R0-R2) and B (R3-R5)
    R3 = DM(I1, M6);
    F0 = F0 + F15;                                      // phase = x + 0.25f
    F3 = F3 + F15;
    F1 = F9 - F0;                                       // 0.0f - phase
    F4 = F9 - F3;
    R1 = TRUNC F1;
    R4 = TRUNC F4;
    R1 = R1 + R11;
    R4 = R4 + R11;
    R1 = R14 OR R1;                                     // itof_nonneg
    R4 = R14 OR R4;
    F1 = F1 - F14;
    F4 = F4 - F14;
